    /*
     * Add to the AppliedPromotions
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	OrderLine
     */
    public OrderLine addToAppliedPromotions( UUID parentId, Promotion addTo ) {
	    LOGGER.info("handling AssignAppliedPromotionsToOrderLineEvent - " );
	    
	    OrderLine parentEntity = repository.findById(parentId).get();
	    Promotion child = registry.project( Promotion.class, addTo.getPromotionId());
	    
	    parentEntity.getAppliedPromotions().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the AppliedPromotions
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	OrderLine
     */
	public OrderLine removeFromAppliedPromotions( UUID parentId, Promotion removeFrom ) {
	    LOGGER.info("handling RemoveAppliedPromotionsFromOrderLineEvent " );
	
	    OrderLine parentEntity = repository.findById(parentId).get();
	    Promotion child = registry.project( Promotion.class, removeFrom.getPromotionId());
	    
	    parentEntity.getAppliedPromotions().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



